<script setup lang="ts">import{onMounted,ref}from'vue';import{site}from'../config';import{api}from'../api';import type{Post}from'../types';import PostCard from'../components/PostCard.vue';const featured=ref<Post[]>([]),latest=ref<Post[]>([]);onMounted(async()=>{[featured.value,latest.value]=await Promise.all([api<Post[]>('/featured'),api<{items:Post[]}>('/posts').then(x=>x.items)])})</script><template><section class="hero"><p class="prompt">&gt; {{site.terminalName}}</p><h1>Build systems.<br><em>Keep thinking.</em></h1><p>{{site.description}}</p><div class="actions"><RouterLink class="button" to="/posts?category=技术">探索技术</RouterLink><RouterLink class="button secondary" to="/posts?category=随笔">阅读随笔</RouterLink></div></section><section><div class="section-title"><h2>精选文章</h2><span>FEATURED</span></div><div class="grid"><PostCard v-for="p in featured" :post="p" :key="p.id"/></div></section><section><div class="section-title"><h2>最新文章</h2><RouterLink to="/posts">查看全部 →</RouterLink></div><div class="grid"><PostCard v-for="p in latest.slice(0,4)" :post="p" :key="p.id"/></div></section></template>
